/**
 * A FILM COMPILED FROM A SHOT LIST — the shots of a video declared once, each with a source slot, and compiled to a
 * plain `<video>` (a `.vid.tsx` the video editor opens and the headless renderer renders), the tasks that ask a
 * person to record what is still missing, and the jobs a build runs to make the rest.
 *
 * A slot is where one shot's footage comes from. It has three modes, and a film switches them per shot or for all:
 *
 *   synth3d     rendered from a 3D scene: the product's own renderer makes `footage/synth3d/<shot>.mp4`
 *   diffusion   generated by a video model: `footage/diffusion/<shot>.<key>.mp4`, where `<key>` is the content hash of
 *               what the model is given (model, prompt, references by their bytes, seed, length, size). The same
 *               inputs name the same file, so an asset is generated again only when one of its inputs changes
 *   real        recorded footage: `footage/real/<shot>.mp4`. While that file is missing the compile returns a task
 *               (`<shot>.task.tsx` and its `.md`: framing, length, lines, props, and the path the upload fills) and
 *               the shot shows its fallback mode's footage, so the film always builds
 *
 * Paths are relative to the compiled video's folder (a clip's `src` is a path from its code). Times are seconds.
 *
 *   const film: Film = {
 *     name: "Launch", width: 1920, height: 1080, fps: 24, mode: "synth3d",
 *     shots: [
 *       { id: "a1", onCamera: true, lead: 1.5, lines: [{ id: "l1", text: "Hello." }],
 *         synth3d: { scene: "speaker" }, real: { framing: "medium close-up, centred, black background" } },
 *       { id: "b1", duration: 4, title: { text: "launch" }, synth3d: { scene: "turntable" },
 *         diffusion: { model: "some/model", prompt: "…", seed: 7 } },
 *     ],
 *   };
 *   const keys = { b1: await diffusionKey(film.shots[1].diffusion!, { width: 1920, height: 1080, fps: 24, duration: 4 }) };
 *   const out = compileFilm(film, { lineSeconds: { l1: 0.8 }, has: (p) => existsSync(join(dir, p)), diffusionKeys: keys });
 *   // out.vid: the `.vid.tsx` text; out.tasks: the real-mode tasks to write; out.jobs: the footage to make
 *
 * This module is pure (no file system, no network): the build that uses it reads and writes the files.
 */
import type { DesignElement } from "./jsx-runtime.js";

export type FootageMode = "synth3d" | "diffusion" | "real";
export const FOOTAGE_MODES: readonly FootageMode[] = ["synth3d", "diffusion", "real"];

/** One line of narration: `text` is what is shown and recorded; `say` what a voice model reads, when it differs. */
export interface FilmLine {
  id: string;
  text: string;
  say?: string;
}

/** The inputs of one generated clip. `refs` are paths of reference images, hashed by their bytes. */
export interface DiffusionSpec {
  model: string;
  prompt: string;
  seed: number;
  refs?: string[];
  /** Anything else the model takes (a negative prompt, a motion strength); part of the key. */
  params?: Record<string, unknown>;
}

/** What a person is asked to record for a shot. */
export interface RealSpec {
  framing: string;
  props?: string[];
  notes?: string;
}

/** What the product's 3D renderer needs to make a shot; `scene` names the scene, the rest is the scene's own. */
export interface Synth3dSpec {
  scene: string;
  [key: string]: unknown;
}

export interface FilmShot {
  id: string;
  /** What the shot shows, for people (a task's title, the clip's name). */
  name?: string;
  /** The narration that starts in this shot, in order. */
  lines?: FilmLine[];
  /** The lines are spoken on camera (lip-synced in synth3d, said to the lens in real). */
  onCamera?: boolean;
  /** The shot's length; with lines, its least length. */
  duration?: number;
  /** Seconds before the first line, between lines, and after the last. */
  lead?: number;
  gap?: number;
  tail?: number;
  title?: { text: string; at?: number; duration?: number; fontSize?: number; color?: string; fontFamily?: string };
  /** The transition into this shot (a kind of the video editor's, e.g. `crossDissolve`). */
  transition?: { kind: string; duration: number };
  /** This shot's mode, over the film's. */
  mode?: FootageMode;
  synth3d?: Synth3dSpec;
  diffusion?: DiffusionSpec;
  real?: RealSpec;
}

export interface Film {
  name: string;
  width: number;
  height: number;
  fps: number;
  /** The mode every shot uses unless it names its own. */
  mode: FootageMode;
  /** What a shot shows while its mode's footage is missing (a real take not yet uploaded); synth3d when not given. */
  fallback?: FootageMode;
  shots: FilmShot[];
  /** Each line's recorded or generated voice is `<voiceDir>/<line id>.wav` ("voice" when not given). */
  voiceDir?: string;
  /** The titles' font family, unless a title names its own. */
  titleFont?: string;
  /** The score, laid from 0 under the whole film. */
  music?: { src: string; volume?: number };
  /** The master's loudness (LUFS integrated) and peak ceiling (dBFS). */
  loudness?: { target: number; peak: number };
}

export interface CompileOptions {
  /** Each line's spoken length in seconds (from its voice file). A line with no length is refused. */
  lineSeconds: Record<string, number>;
  /** Whether a file exists, by path from the video's folder. */
  has: (path: string) => boolean;
  /** Each diffusion shot's key (`diffusionKey`), by shot id. */
  diffusionKeys?: Record<string, string>;
  /** Modes over the film's and the shots' own: `{ "*": "real" }` for all, `{ a1: "diffusion" }` for one. */
  modes?: Record<string, FootageMode>;
}

export interface CompiledShot {
  id: string;
  start: number;
  duration: number;
  /** The mode asked for, and the one whose footage the clip shows. */
  mode: FootageMode;
  shows: FootageMode;
  src: string;
  lines: { id: string; text: string; start: number; duration: number; src: string }[];
}

export interface FootageJob {
  shot: string;
  mode: "synth3d" | "diffusion";
  out: string;
  start: number;
  duration: number;
  spec: Synth3dSpec | DiffusionSpec;
  key?: string;
  onCamera: boolean;
  lines: CompiledShot["lines"];
  /** The file is there: nothing to make. */
  cached: boolean;
}

export interface FootageTask {
  shot: string;
  /** `tasks/<shot>.task.tsx` and `tasks/<shot>.md`, by path from the video's folder. */
  path: string;
  readmePath: string;
  tsx: string;
  md: string;
}

export interface CompiledFilm {
  shots: CompiledShot[];
  duration: number;
  video: DesignElement;
  /** The `.vid.tsx` text of `video`. */
  vid: string;
  jobs: FootageJob[];
  tasks: FootageTask[];
}

const r3 = (x: number) => Math.round(x * 1000) / 1000;

/** The file a shot's footage is in, in a mode. A diffusion clip's file names its key. */
export function footagePath(shot: string, mode: FootageMode, key?: string): string {
  if (mode === "diffusion") {
    if (!key) throw new Error(`shot ${shot}: a diffusion clip's file is named by its key (diffusionKey)`);
    return `footage/diffusion/${shot}.${key.slice(0, 16)}.mp4`;
  }
  return `footage/${mode}/${shot}.mp4`;
}

/** JSON with the keys of every object sorted, so equal values have equal text. */
export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value && typeof value === "object") {
    const o = value as Record<string, unknown>;
    return `{${Object.keys(o)
      .filter((k) => o[k] !== undefined)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`)
      .join(",")}}`;
  }
  if (typeof value === "number" && !Number.isFinite(value)) throw new Error(`canonicalJson: ${value} is not a JSON number`);
  return JSON.stringify(value) ?? "null";
}

async function sha256Hex(bytes: Uint8Array | string): Promise<string> {
  const data = typeof bytes === "string" ? new TextEncoder().encode(bytes) : bytes;
  const digest = await globalThis.crypto.subtle.digest("SHA-256", data as BufferSource);
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

/**
 * The content hash that names a generated clip: sha256 of the canonical JSON of everything the model is given. A
 * reference counts by its bytes (`refBytes[path]`), not its name, so a changed image changes the key and a renamed
 * one does not. Reference order counts (models weigh the first most).
 */
export async function diffusionKey(
  spec: DiffusionSpec,
  shape: { width: number; height: number; fps: number; duration: number },
  refBytes: Record<string, Uint8Array> = {},
): Promise<string> {
  const refs: string[] = [];
  for (const ref of spec.refs ?? []) {
    const bytes = refBytes[ref];
    if (!bytes) throw new Error(`diffusionKey: the reference ${ref} was not read`);
    refs.push(await sha256Hex(bytes));
  }
  return sha256Hex(
    canonicalJson({
      model: spec.model,
      prompt: spec.prompt,
      seed: spec.seed,
      refs,
      params: spec.params ?? {},
      width: shape.width,
      height: shape.height,
      fps: shape.fps,
      duration: r3(shape.duration),
    }),
  );
}

/** A shot's length from its lines: lead, each line with the gap between, tail; at least its `duration`. */
export function shotSeconds(shot: FilmShot, lineSeconds: Record<string, number>): number {
  const lines = shot.lines ?? [];
  if (!lines.length) {
    if (!(shot.duration! > 0)) throw new Error(`shot ${shot.id}: a shot with no lines needs a duration`);
    return shot.duration!;
  }
  let t = shot.lead ?? 0;
  lines.forEach((l, i) => {
    const s = lineSeconds[l.id];
    if (s === undefined || !(s > 0)) throw new Error(`shot ${shot.id}: line ${l.id} has no spoken length`);
    t += s + (i < lines.length - 1 ? (shot.gap ?? 0.35) : 0);
  });
  t += shot.tail ?? 0.5;
  return Math.max(t, shot.duration ?? 0);
}

/** A shot's mode: named for it, else the build's mode for all (when the shot has that slot), else its own, else the film's. */
function modeOf(film: Film, shot: FilmShot, modes: Record<string, FootageMode> = {}): FootageMode {
  const all = modes["*"];
  const m = modes[shot.id] ?? (all && shot[all] ? all : undefined) ?? shot.mode ?? film.mode;
  if (!FOOTAGE_MODES.includes(m)) throw new Error(`shot ${shot.id}: ${m} is not a footage mode (${FOOTAGE_MODES.join(", ")})`);
  return m;
}

const el = (type: string, props: Record<string, unknown>, children: DesignElement[] = []): DesignElement => ({
  $$design: "element",
  type,
  props: children.length ? { ...props, children } : props,
});

const fmt = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toFixed(1).padStart(4, "0")}`;

function taskFor(film: Film, shot: FilmShot, c: CompiledShot): FootageTask {
  const real = shot.real!;
  const title = `Record shot ${shot.id} of ${film.name}${shot.name ? `: ${shot.name}` : ""}`;
  const id = `film-${film.name}-${shot.id}`.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  const take = Math.ceil(c.duration + 2);
  const md = [
    `# ${title}`,
    "",
    `The film \`${film.name}\` needs this shot recorded. Until it is, the film shows its ${film.fallback ?? "synth3d"} version.`,
    "",
    `- **Upload to:** \`${footagePath(shot.id, "real")}\`, by path from the video's folder (${film.name}.vid.tsx). The next build uses it.`,
    `- **Length:** ${c.duration.toFixed(1)} s on the timeline (${fmt(c.start)}–${fmt(c.start + c.duration)}); record at least ${take} s, ${film.width} × ${film.height}, ${film.fps} fps or more.`,
    `- **Framing:** ${real.framing}`,
    ...(real.props?.length ? [`- **Props:** ${real.props.join("; ")}`] : []),
    ...(real.notes ? [`- **Notes:** ${real.notes}`] : []),
    ...(c.lines.length
      ? [
          `- **Lines** (${shot.onCamera ? "said on camera, to the lens" : "voice-over: record the picture only"}):`,
          ...c.lines.map((l) => `  - ${(l.start - c.start).toFixed(1)} s in: "${l.text}"`),
        ]
      : []),
    "",
    `accept: ${footagePath(shot.id, "real")} holds a take of at least ${take} s`,
    "",
  ].join("\n");
  const tsx = [
    `// Written by the film's build (commandagi/design footage.ts) because ${footagePath(shot.id, "real")} is missing.`,
    `// The build never rewrites this file once it exists: close it here when the take is uploaded.`,
    "export default () => (",
    `  <task id=${JSON.stringify(id)} title=${JSON.stringify(title)} status="todo" priority="high" labels={["film", "footage"]} readme=${JSON.stringify(`${shot.id}.md`)} />`,
    ");",
    "",
  ].join("\n");
  return { shot: shot.id, path: `tasks/${shot.id}.task.tsx`, readmePath: `tasks/${shot.id}.md`, tsx, md };
}

/**
 * The film as a timeline: each shot after the one before, as long as its lines (`shotSeconds`), on V1 a clip of its
 * footage, on V2 its title, on A1 each line's voice and on A2 the score. Returns the video, its code, the jobs that
 * make the footage the modes ask for, and a task for each real shot whose take is missing.
 */
export function compileFilm(film: Film, opts: CompileOptions): CompiledFilm {
  const voiceDir = film.voiceDir ?? "voice";
  const fallback = film.fallback ?? "synth3d";
  if (fallback === "real") throw new Error("a film's fallback is a mode the build makes: synth3d or diffusion");
  const ids = new Set<string>();
  const shots: CompiledShot[] = [];
  const jobs: FootageJob[] = [];
  const tasks: FootageTask[] = [];
  let t = 0;
  for (const shot of film.shots) {
    if (ids.has(shot.id)) throw new Error(`shot ${shot.id} is declared twice`);
    ids.add(shot.id);
    const duration = r3(shotSeconds(shot, opts.lineSeconds));
    const start = r3(t);
    const lines: CompiledShot["lines"] = [];
    let lt = start + (shot.lead ?? 0);
    for (const l of shot.lines ?? []) {
      const d = opts.lineSeconds[l.id]!;
      lines.push({ id: l.id, text: l.text, start: r3(lt), duration: r3(d), src: `${voiceDir}/${l.id}.wav` });
      lt += d + (shot.gap ?? 0.35);
    }
    const mode = modeOf(film, shot, opts.modes);
    const job = (m: "synth3d" | "diffusion"): string => {
      const spec = m === "synth3d" ? shot.synth3d : shot.diffusion;
      if (!spec) throw new Error(`shot ${shot.id} has no ${m} slot`);
      const key = m === "diffusion" ? opts.diffusionKeys?.[shot.id] : undefined;
      const out = footagePath(shot.id, m, key);
      jobs.push({ shot: shot.id, mode: m, out, start, duration, spec, key, onCamera: !!shot.onCamera, lines, cached: opts.has(out) });
      return out;
    };
    let src: string;
    let shows: FootageMode = mode;
    if (mode === "real") {
      if (!shot.real) throw new Error(`shot ${shot.id} has no real slot`);
      src = footagePath(shot.id, "real");
      const c = { id: shot.id, start, duration, mode, shows, src, lines };
      if (!opts.has(src)) {
        tasks.push(taskFor(film, shot, c));
        shows = fallback;
        src = job(fallback);
      }
    } else {
      src = job(mode);
    }
    shots.push({ id: shot.id, start, duration, mode, shows, src, lines });
    t += duration;
  }
  const total = r3(t);

  const clip = (s: CompiledShot, shot: FilmShot) =>
    el(
      "clip",
      { name: shot.name ?? s.id, src: s.src, start: s.start, in: 0, out: s.duration, volume: 0 },
      shot.transition ? [el("transition", { kind: shot.transition.kind, duration: shot.transition.duration })] : [],
    );
  const titles = film.shots.flatMap((shot, i) => {
    if (!shot.title) return [];
    const s = shots[i]!;
    const at = shot.title.at ?? 0;
    const props: Record<string, unknown> = {
      text: shot.title.text,
      start: r3(s.start + at),
      duration: r3(shot.title.duration ?? s.duration - at),
      fontSize: shot.title.fontSize ?? Math.round(film.height / 18),
      color: shot.title.color ?? "#e8e8e8",
    };
    const font = shot.title.fontFamily ?? film.titleFont;
    if (font) props.fontFamily = font;
    return [el("title", props)];
  });
  const voice = shots.flatMap((s) => s.lines.map((l) => el("clip", { name: l.id, src: l.src, start: l.start, in: 0, out: l.duration })));
  // Tracks are front-most first: the titles over the footage (the renderer's base layer is the bottom video track).
  const tracks = [
    ...(titles.length ? [el("track", { name: "Titles" }, titles)] : []),
    el("track", { name: "V1" }, shots.map((s, i) => clip(s, film.shots[i]!))),
    el("track", { name: "Voice", kind: "audio" }, voice),
    ...(film.music ? [el("track", { name: "Score", kind: "audio" }, [el("clip", { src: film.music.src, start: 0, in: 0, out: total, volume: film.music.volume ?? 1 })])] : []),
  ];
  const master = film.loudness ? [el("loudness", { target: film.loudness.target, peak: film.loudness.peak })] : [];
  const video = el("video", { name: film.name, width: film.width, height: film.height, fps: film.fps, background: "#000000" }, [...tracks, ...master]);
  const header = [
    `// ${film.name}: compiled from its shot list by commandagi/design footage.ts. Build again rather than editing this file.`,
    `// ${shots.length} shots, ${total.toFixed(1)} s. Footage: ${FOOTAGE_MODES.map((m) => `${m} ${shots.filter((s) => s.shows === m).length}`).join(", ")}.`,
  ];
  return { shots, duration: total, video, vid: `${header.join("\n")}\nexport default () => (\n${printElement(video, 1)}\n);\n`, jobs, tasks };
}

const attr = (v: unknown): string => (typeof v === "string" ? JSON.stringify(v) : `{${typeof v === "object" ? canonicalJson(v) : String(v)}}`);

/** An element as TSX, one element per line, attributes in the order given. */
export function printElement(e: DesignElement, depth = 0): string {
  const pad = "  ".repeat(depth);
  const { children, ...props } = e.props as Record<string, unknown> & { children?: DesignElement[] };
  const attrs = Object.entries(props)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => ` ${k}=${attr(v)}`)
    .join("");
  if (!children?.length) return `${pad}<${e.type}${attrs} />`;
  return `${pad}<${e.type}${attrs}>\n${children.map((c) => printElement(c, depth + 1)).join("\n")}\n${pad}</${e.type}>`;
}
